{"command": "create", "path": "/root/output/js/visualization.js", "file_text": "// Stock bubble chart + data table using D3.js v6.
// Data: data/stock-descriptions.csv (50 stocks across 5 sectors; ETFs have no marketCap).

(function () {
    'use strict';

    const CHART_WIDTH = 760;
    const CHART_HEIGHT = 620;
    const CHART_MARGIN = { top: 20, right: 20, bottom: 20, left: 20 };

    // Deterministic sector order (sorted alphabetically for stable color mapping).
    const SECTOR_ORDER = ['Energy', 'ETF', 'Financial', 'Industry', 'Information Technology'];

    // Pick a palette with 5 distinct, pleasant colors.
    const SECTOR_COLORS = {
        'Information Technology': '#4e79a7',
        'Industry':               '#f28e2b',
        'Energy':                 '#e15759',
        'Financial':              '#59a14f',
        'ETF':                    '#9c6ade'
    };

    // Radius bounds for stocks with marketCap. ETFs use a fixed radius.
    const MIN_RADIUS = 14;
    const MAX_RADIUS = 52;
    const ETF_RADIUS = 26;

    // Format a market-cap number as "1.64T", "193.22B", "250.00M".
    function formatMarketCap(v) {
        if (v == null || Number.isNaN(v) || v === 0) return null;
        const abs = Math.abs(v);
        if (abs >= 1e12) return (v / 1e12).toFixed(2) + 'T';
        if (abs >= 1e9)  return (v / 1e9).toFixed(2) + 'B';
        if (abs >= 1e6)  return (v / 1e6).toFixed(2) + 'M';
        return v.toLocaleString();
    }

    // Compute 5 cluster centers in a centered pentagon (plus center offset).
    function clusterCenters(sectors, cx, cy, radius) {
        const centers = {};
        const n = sectors.length;
        sectors.forEach((s, i) => {
            // Start at top (-90°) and go clockwise.
            const angle = (-Math.PI / 2) + (i * 2 * Math.PI / n);
            centers[s] = {
                x: cx + radius * Math.cos(angle),
                y: cy + radius * Math.sin(angle)
            };
        });
        return centers;
    }

    d3.csv('data/stock-descriptions.csv').then((rows) => {
        // Parse rows into node objects.
        const nodes = rows.map((r, i) => {
            const mc = r.marketCap && r.marketCap !== '' ? +r.marketCap : null;
            return {
                index: i,
                ticker: r.ticker,
                name: r['full name'],
                sector: r.sector,
                marketCap: mc,
                country: r.country || '',
                website: r.website || '',
                isETF: r.sector === 'ETF'
            };
        });

        // Sort nodes deterministically for stable table + initial layout.
        nodes.sort((a, b) => {
            const sa = SECTOR_ORDER.indexOf(a.sector);
            const sb = SECTOR_ORDER.indexOf(b.sector);
            if (sa !== sb) return sa - sb;
            // Within sector, bigger market cap first; ETFs sort by ticker.
            if (a.isETF && b.isETF) return d3.ascending(a.ticker, b.ticker);
            return d3.descending(a.marketCap || 0, b.marketCap || 0);
        });

        // Radius scale: use sqrt so area is roughly proportional to market cap.
        const stockCaps = nodes.filter(d => !d.isETF && d.marketCap).map(d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([d3.min(stockCaps), d3.max(stockCaps)])
            .range([MIN_RADIUS, MAX_RADIUS]);

        nodes.forEach(d => {
            d.radius = d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
        });

        drawLegend();
        drawBubbleChart(nodes);
        drawTable(nodes);
        wireInteractions();
    });

    // ---------- Legend ----------
    function drawLegend() {
        const legend = d3.select('#legend');
        legend.selectAll('.legend-item')
            .data(SECTOR_ORDER)
            .enter()
            .append('div')
            .attr('class', 'legend-item')
            .html(s => `
                <span class="legend-swatch" style="background:${SECTOR_COLORS[s]}"></span>
                <span>${s}</span>
            `);
    }

    // ---------- Bubble chart ----------
    function drawBubbleChart(nodes) {
        const svg = d3.select('#bubble-chart')
            .append('svg')
            .attr('viewBox', `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
            .attr('preserveAspectRatio', 'xMidYMid meet');

        const innerW = CHART_WIDTH - CHART_MARGIN.left - CHART_MARGIN.right;
        const innerH = CHART_HEIGHT - CHART_MARGIN.top - CHART_MARGIN.bottom;
        const cx = CHART_MARGIN.left + innerW / 2;
        const cy = CHART_MARGIN.top + innerH / 2;

        // Pentagon radius chosen to keep clusters inside the chart and close together.
        const centers = clusterCenters(SECTOR_ORDER, cx, cy, Math.min(innerW, innerH) * 0.26);

        // Seed initial positions near each cluster center for a stable starting layout.
        nodes.forEach((d, i) => {
            const c = centers[d.sector];
            // Deterministic offset based on index so no RNG is needed.
            const theta = (i * 2.399);  // golden-angle for a nice spread
            const r = 8 + (i % 5) * 3;
            d.x = c.x + Math.cos(theta) * r;
            d.y = c.y + Math.sin(theta) * r;
        });

        const g = svg.append('g').attr('class', 'bubbles');

        const bubble = g.selectAll('g.bubble-group')
            .data(nodes, d => d.ticker)
            .enter()
            .append('g')
            .attr('class', 'bubble-group');

        bubble.append('circle')
            .attr('class', 'bubble')
            .attr('data-ticker', d => d.ticker)
            .attr('r', d => d.radius)
            .attr('fill', d => SECTOR_COLORS[d.sector])
            .attr('fill-opacity', 0.85);

        bubble.append('text')
            .attr('class', 'bubble-label')
            .text(d => d.ticker)
            .attr('font-size', d => Math.max(9, Math.min(14, d.radius * 0.45)));

        // Tooltip handlers (ETFs skipped per requirements).
        const tooltip = d3.select('#tooltip');
        bubble
            .on('mouseover', function (event, d) {
                if (d.isETF) return;
                tooltip
                    .classed('visible', true)
                    .html(`
                        <div class="tt-ticker">${d.ticker}</div>
                        <div class="tt-name">${d.name}</div>
                        <div class="tt-sector">${d.sector}</div>
                    `);
            })
            .on('mousemove', function (event, d) {
                if (d.isETF) return;
                tooltip
                    .style('left', (event.pageX + 14) + 'px')
                    .style('top',  (event.pageY + 14) + 'px');
            })
            .on('mouseout', function () {
                tooltip.classed('visible', false);
            })
            .on('click', function (event, d) {
                selectTicker(d.ticker);
            });

        // Force simulation: cluster by sector, prevent overlap.
        const simulation = d3.forceSimulation(nodes)
            .force('x', d3.forceX(d => centers[d.sector].x).strength(0.18))
            .force('y', d3.forceY(d => centers[d.sector].y).strength(0.18))
            .force('charge', d3.forceManyBody().strength(-12))
            .force('collide', d3.forceCollide(d => d.radius + 1.5).strength(0.9))
            .alpha(1)
            .alphaDecay(0.035)
            .on('tick', () => {
                // Keep bubbles inside the chart area.
                nodes.forEach(d => {
                    d.x = Math.max(CHART_MARGIN.left + d.radius,
                                   Math.min(CHART_WIDTH - CHART_MARGIN.right - d.radius, d.x));
                    d.y = Math.max(CHART_MARGIN.top + d.radius,
                                   Math.min(CHART_HEIGHT - CHART_MARGIN.bottom - d.radius, d.y));
                });
                bubble.attr('transform', d => `translate(${d.x},${d.y})`);
            });

        // Expose for interactions.
        window.__viz = Object.assign(window.__viz || {}, {
            svg,
            bubble,
            simulation,
            nodes
        });
    }

    // ---------- Data table ----------
    function drawTable(nodes) {
        const container = d3.select('#table-container');

        const table = container.append('table').attr('class', 'stock-table');
        const thead = table.append('thead').append('tr');

        ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'].forEach(col => {
            thead.append('th').text(col);
        });

        const tbody = table.append('tbody');

        const rows = tbody.selectAll('tr')
            .data(nodes, d => d.ticker)
            .enter()
            .append('tr')
            .attr('data-ticker', d => d.ticker)
            .on('click', function (event, d) {
                selectTicker(d.ticker);
            });

        rows.append('td').attr('class', 'ticker').text(d => d.ticker);
        rows.append('td').text(d => d.name);
        rows.append('td').append('span')
            .attr('class', 'sector-tag')
            .style('background', d => SECTOR_COLORS[d.sector])
            .text(d => d.sector);
        rows.append('td')
            .attr('class', d => {
                const f = formatMarketCap(d.marketCap);
                return 'marketcap' + (f == null ? ' na' : '');
            })
            .text(d => {
                const f = formatMarketCap(d.marketCap);
