// Data: data/stock-descriptions.csv (50 stocks across 5 sectors; ETFs have no marketCap).

(function () {
    'use strict';

    const CHART_WIDTH = 760;
    const CHART_HEIGHT = 620;
    const CHART_MARGIN = { top: 20, right: 20, bottom: 20, left: 20 };

    // Deterministic sector order (sorted alphabetically for stable color mapping).
    const SECTOR_ORDER = ['Energy', 'ETF', 'Financial', 'Industry', 'Information Technology'];

    // Pick a palette with 5 distinct, pleasant colors.
    const SECTOR_COLORS = {
        'Information Technology': '#4e79a7',
        'Industry':               '#f28e2b',
        'Energy':                 '#e15759',
        'Financial':              '#59a14f',
        'ETF':                    '#9c6ade'
    };

    // Radius bounds for stocks with marketCap. ETFs use a fixed radius.
    const MIN_RADIUS = 14;
    const MAX_RADIUS = 52;
    const ETF_RADIUS = 26;

    // Format a market-cap number as "1.64T", "193.22B", "250.00M".
    function formatMarketCap(v) {
        if (v == null || Number.isNaN(v) || v === 0) return null;
        const abs = Math.abs(v);
        if (abs >= 1e12) return (v / 1e12).toFixed(2) + 'T';
        if (abs >= 1e9)  return (v / 1e9).toFixed(2) + 'B';
        if (abs >= 1e6)  return (v / 1e6).toFixed(2) + 'M';
        return v.toLocaleString();
    }

    // Compute 5 cluster centers in a centered pentagon (plus center offset).
    function clusterCenters(sectors, cx, cy, radius) {
        const centers = {};
        const n = sectors.length;
        sectors.forEach((s, i) => {
            // Start at top (-90°) and go clockwise.
            const angle = (-Math.PI / 2) + (i * 2 * Math.PI / n);
            centers[s] = {
                x: cx + radius * Math.cos(angle),
                y: cy + radius * Math.sin(angle)
            };
        });
        return centers;
    }

    d3.csv('data/stock-descriptions.csv').then((rows) => {
        // Parse rows into node objects.
        const nodes = rows.map((r, i) => {
            const mc = r.marketCap && r.marketCap !== '' ? +r.marketCap : null;
            return {
                index: i,
                ticker: r.ticker,
                name: r['full name'],
                sector: r.sector,
                marketCap: mc,
                country: r.country || '',
                website: r.website || '',
                isETF: r.sector === 'ETF'
            };
