        const stockCaps = nodes.filter(d => !d.isETF && d.marketCap).map(d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([d3.min(stockCaps), d3.max(stockCaps)])
            .range([MIN_RADIUS, MAX_RADIUS]);

