    }

    // ---------- Linked selection ----------
    function wireInteractions() {
        // Clicking the empty chart background clears selection.
        d3.select('#bubble-chart svg').on('click', function (event) {
            if (event.target.tagName === 'svg') selectTicker(null);
        });
    }

    function selectTicker(ticker) {
        const v = window.__viz;
