{"command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
    --bg: #f6f7fb;
    --panel: #ffffff;
    --border: #e3e5ec;
    --text: #1f2330;
    --muted: #6b7280;
    --accent: #1f6feb;
    --highlight: #ffe79a;
    --highlight-stroke: #d97706;
}

* { box-sizing: border-box; }

html, body {
    margin: 0;
    padding: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
}

header {
    padding: 20px 28px 8px;
}

header h1 {
    margin: 0 0 6px 0;
    font-size: 22px;
    font-weight: 600;
}

.subtitle {
    margin: 0;
    color: var(--muted);
    font-size: 13px;
}

.layout {
    display: flex;
    flex-direction: row;
    gap: 24px;
    padding: 16px 28px 28px;
    align-items: flex-start;
}

.chart-panel,
.table-panel {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 16px;
    box-shadow: 0 1px 2px rgba(16, 24, 40, 0.04);
}

.chart-panel {
    flex: 0 0 760px;
}

.table-panel {
    flex: 1 1 auto;
    min-width: 420px;
    max-height: 760px;
    overflow: auto;
}

#legend {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 18px;
    margin-bottom: 10px;
    font-size: 12px;
    color: var(--text);
}

.legend-item {
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.legend-swatch {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    display: inline-block;
    border: 1px solid rgba(0, 0, 0, 0.1);
}

#bubble-chart svg {
    display: block;
    width: 100%;
    height: auto;
}

circle.bubble {
    cursor: pointer;
    stroke: #ffffff;
    stroke-width: 1.5px;
    transition: stroke 0.15s, stroke-width 0.15s;
}

circle.bubble:hover {
    stroke: #333;
    stroke-width: 2px;
}

circle.bubble.selected {
    stroke: var(--highlight-stroke);
    stroke-width: 3.5px;
}

text.bubble-label {
    font-size: 11px;
    font-weight: 600;
    fill: #ffffff;
    text-anchor: middle;
    dominant-baseline: central;
    pointer-events: none;
    paint-order: stroke;
    stroke: rgba(0, 0, 0, 0.35);
    stroke-width: 2px;
    stroke-linejoin: round;
}

table.stock-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
}

table.stock-table thead th {
    position: sticky;
    top: 0;
    background: #f0f2f8;
    text-align: left;
    padding: 10px 12px;
    border-bottom: 2px solid var(--border);
    font-weight: 600;
    color: var(--text);
    z-index: 1;
}

table.stock-table tbody td {
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
    vertical-align: top;
}

table.stock-table tbody tr {
    cursor: pointer;
}

table.stock-table tbody tr:hover {
    background: #f8f9fc;
}

table.stock-table tbody tr.selected {
    background: var(--highlight);
}

table.stock-table tbody tr.selected td {
    font-weight: 600;
}

td.ticker {
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-weight: 600;
}

td.marketcap {
    text-align: right;
    font-variant-numeric: tabular-nums;
}

td.na {
    color: var(--muted);
    font-style: italic;
}

.sector-tag {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 11px;
    color: #ffffff;
    font-weight: 500;
}

.tooltip {
