        wireInteractions();
    });

    // ---------- Legend ----------
    function drawLegend() {
        const legend = d3.select('#legend');
        legend.selectAll('.legend-item')
            .data(SECTOR_ORDER)
            .enter()
            .append('div')
            .attr('class', 'legend-item')
            .html(s => `
                <span class="legend-swatch" style="background:${SECTOR_COLORS[s]}"></span>
                <span>${s}</span>
            `);
    }

    // ---------- Bubble chart ----------
    function drawBubbleChart(nodes) {
        const svg = d3.select('#bubble-chart')
            .append('svg')
            .attr('viewBox', `0 0 ${CHART_WIDTH} ${CHART_HEIGHT}`)
            .attr('preserveAspectRatio', 'xMidYMid meet');

        const innerW = CHART_WIDTH - CHART_MARGIN.left - CHART_MARGIN.right;
        const innerH = CHART_HEIGHT - CHART_MARGIN.top - CHART_MARGIN.bottom;
        const cx = CHART_MARGIN.left + innerW / 2;
        const cy = CHART_MARGIN.top + innerH / 2;

        // Pentagon radius chosen to keep clusters inside the chart and close together.
        const centers = clusterCenters(SECTOR_ORDER, cx, cy, Math.min(innerW, innerH) * 0.26);

        // Seed initial positions near each cluster center for a stable starting layout.
        nodes.forEach((d, i) => {
            const c = centers[d.sector];
            // Deterministic offset based on index so no RNG is needed.
            const theta = (i * 2.399);  // golden-angle for a nice spread
            const r = 8 + (i % 5) * 3;
            d.x = c.x + Math.cos(theta) * r;
            d.y = c.y + Math.sin(theta) * r;
        });

        const g = svg.append('g').attr('class', 'bubbles');

        const bubble = g.selectAll('g.bubble-group')
            .data(nodes, d => d.ticker)
            .enter()
            .append('g')
            .attr('class', 'bubble-group');

        bubble.append('circle')
            .attr('class', 'bubble')
            .attr('data-ticker', d => d.ticker)
            .attr('r', d => d.radius)
            .attr('fill', d => SECTOR_COLORS[d.sector])
            .attr('fill-opacity', 0.85);

        bubble.append('text')
            .attr('class', 'bubble-label')
            .text(d => d.ticker)
            .attr('font-size', d => Math.max(9, Math.min(14, d.radius * 0.45)));

        // Tooltip handlers (ETFs skipped per requirements).
        const tooltip = d3.select('#tooltip');
        bubble
            .on('mouseover', function (event, d) {
                if (d.isETF) return;
                tooltip
                    .classed('visible', true)
                    .html(`
                        <div class="tt-ticker">${d.ticker}</div>
                        <div class="tt-name">${d.name}</div>
                        <div class="tt-sector">${d.sector}</div>
                    `);
            })
            .on('mousemove', function (event, d) {
                if (d.isETF) return;
                tooltip
                    .style('left', (event.pageX + 14) + 'px')
                    .style('top',  (event.pageY + 14) + 'px');
            })
            .on('mouseout', function () {
                tooltip.classed('visible', false);
            })
            .on('click', function (event, d) {
                selectTicker(d.ticker);
            });

