        const simulation = d3.forceSimulation(nodes)
            .force('x', d3.forceX(d => centers[d.sector].x).strength(0.18))
            .force('y', d3.forceY(d => centers[d.sector].y).strength(0.18))
            .force('charge', d3.forceManyBody().strength(-12))
            .force('collide', d3.forceCollide(d => d.radius + 1.5).strength(0.9))
            .alpha(1)
            .alphaDecay(0.035)
            .on('tick', () => {
                // Keep bubbles inside the chart area.
                nodes.forEach(d => {
                    d.x = Math.max(CHART_MARGIN.left + d.radius,
                                   Math.min(CHART_WIDTH - CHART_MARGIN.right - d.radius, d.x));
                    d.y = Math.max(CHART_MARGIN.top + d.radius,
                                   Math.min(CHART_HEIGHT - CHART_MARGIN.bottom - d.radius, d.y));
                });
                bubble.attr('transform', d => `translate(${d.x},${d.y})`);
            });

        // Expose for interactions.
        window.__viz = Object.assign(window.__viz || {}, {
            svg,
            bubble,
            simulation,
            nodes
        });
    }

    // ---------- Data table ----------
    function drawTable(nodes) {
        const container = d3.select('#table-container');

        const table = container.append('table').attr('class', 'stock-table');
        const thead = table.append('thead').append('tr');

        ['Ticker symbol', 'Full company name', 'Sector', 'Market cap'].forEach(col => {
            thead.append('th').text(col);
        });

        const tbody = table.append('tbody');

        const rows = tbody.selectAll('tr')
            .data(nodes, d => d.ticker)
            .enter()
            .append('tr')
            .attr('data-ticker', d => d.ticker)
            .on('click', function (event, d) {
                selectTicker(d.ticker);
            });

        rows.append('td').attr('class', 'ticker').text(d => d.ticker);
        rows.append('td').text(d => d.name);
        rows.append('td').append('span')
            .attr('class', 'sector-tag')
            .style('background', d => SECTOR_COLORS[d.sector])
            .text(d => d.sector);
        rows.append('td')
            .attr('class', d => {
                const f = formatMarketCap(d.marketCap);
                return 'marketcap' + (f == null ? ' na' : '');
            })
            .text(d => {
                const f = formatMarketCap(d.marketCap);
                return f == null ? '—' : f;
            });

        window.__viz = Object.assign(window.__viz || {}, { rows });
    }

    // ---------- Linked selection ----------
    function wireInteractions() {
        // Clicking the empty chart background clears selection.
        d3.select('#bubble-chart svg').on('click', function (event) {
            if (event.target.tagName === 'svg') selectTicker(null);
        });
    }

    function selectTicker(ticker) {
        const v = window.__viz;
        if (!v) return;

        v.bubble.selectAll('circle.bubble')
