        // Parse rows into node objects.
        const nodes = rows.map((r, i) => {
            const mc = r.marketCap && r.marketCap !== '' ? +r.marketCap : null;
            return {
                index: i,
                ticker: r.ticker,
                name: r['full name'],
                sector: r.sector,
                marketCap: mc,
                country: r.country || '',
                website: r.website || '',
                isETF: r.sector === 'ETF'
            };
