    }

    // ---------- Linked selection ----------
    function wireInteractions() {
        // Clicking the empty chart background clears selection.
        d3.select('#bubble-chart svg').on('click', function (event) {
            if (event.target.tagName === 'svg') selectTicker(null);
        });
    }

    function selectTicker(ticker) {
        const v = window.__viz;
        if (!v) return;

        v.bubble.selectAll('circle.bubble')
            .classed('selected', d => ticker != null && d.ticker === ticker);
        v.rows.classed('selected', d => ticker != null && d.ticker === ticker);

        if (ticker == null) return;

        // Scroll the selected row into view inside the table panel.
        const node = document.querySelector(`tr[data-ticker="${ticker}"]`);
        if (node && typeof node.scrollIntoView === 'function') {
            node.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        }
    }
